        toast(acc ? `\u5B9A\u4F4D\u7CBE\u5EA6\u7EA6 \xB1${acc} \u7C73\uFF0C\u53EF\u4EE5\u62D6\u5730\u56FE\u5FAE\u8C03` : "\u5DF2\u5B9A\u4F4D", 2800);
